rows = await query_database({"sql": "SELECT c.id, c.name, SUM(o.total) AS spend FROM customers c JOIN orders o ON o.customer_id = c.id WHERE c.tier = 'bronze' AND o.status = 'completed' GROUP BY c.id, c.name HAVING SUM(o.total) > 2000 ORDER BY spend DESC, c.id ASC"})
await submit_answer({"candidates": [{"id": int(row["id"]), "name": row["name"], "spend": round(float(row["spend"]), 2)} for row in rows]})
